        Blocks(
            Describe.Lean(DescribeId.Create("law-moment-vector"), DeclarationHandle.Create(Prefix + "lawMomentVector"), H("Retained moment vector"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Collect a finite family of rational atom features into their expectation vector under one normalized response law."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("profile-affine-rank"), DeclarationHandle.Create(Prefix + "profileAffineRank"), H("Affine rank of joint atom profiles"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Measure the affine dimension of the range of the retained feature map. Duplicate profiles and affine dependencies do not increase this rank."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("law-moment-vector-convex-hull"), DeclarationHandle.Create(Prefix + "lawMomentVector_mem_convexHull"), H("Moments lie in the atom-profile convex hull"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Normalization and nonnegativity express the retained moment vector as a convex combination of original atom profiles."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("moment-compression"), DeclarationHandle.Create(Prefix + "MomentCompression"), H("Positive sparse moment witness"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A compression stores original feature profiles, positive normalized weights, exact moment equality, affine independence, and a finite cardinality bound."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("exists-moment-compression"), DeclarationHandle.Create(Prefix + "exists_momentCompression"), H("Every finite law has a small exact moment witness"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Mathlib Caratheodory reduction selects an affinely independent positive atomic representation of the exact moment vector."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("card-le-profile-affine-rank"), DeclarationHandle.Create(Prefix + "MomentCompression.card_le_profileAffineRank"), H("Profile rank controls sparse support"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The retained atom count is at most one plus the affine rank of the full joint feature-profile family, sharpening the ambient coordinate count when rows are redundant."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("source-atom"), DeclarationHandle.Create(Prefix + "MomentCompression.sourceAtom"), H("Choose an original atom for each profile"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Each retained profile is certified to occur among the original atoms, so one source atom is chosen for every latent profile."))), DescribeRole.Definition),
